#!/bin/sh
# >>> shguard modes=exec (generated by shell-disposition-gate --guard; do not edit)
case $(realpath -- "$0" 2>/dev/null) in */'util/dispatch.sh') _shguard_m='exec' ;; *) if [ "${SHGUARD_MODE-}" = 'pipe' ]; then _shguard_m='pipe'; else _shguard_m='source'; fi ;; esac
# shellcheck disable=SC2317
case $_shguard_m in
  exec) unset _shguard_m ;;
  *) printf '%s: refusing %s invocation (supports: exec; pipe callers set SHGUARD_MODE=pipe)\n' 'dispatch.sh' "$_shguard_m" >&2; unset _shguard_m; return 1 2>/dev/null || exit 1 ;;
esac
# <<< shguard
case "${1:-}" in --help|-h)
	printf 'usage: %s %s\n' "${0##*/}" '<command> [args...]'
	printf '%s\n' 'Route to util/<command>[.sh]; run with no arguments to list commands.'
	exit 0;; esac
# Router flags: only a leading --build/--version is the router's own (--help still wins).
case "${1:-}" in --build|--version)
	case " $* " in *" --help "*|*" -h "*) exec "$0" --help ;; esac
	# shellcheck source=util/lib/build-id.sh
	. "$(dirname "$(realpath "$0")")/lib/build-id.sh"; build_flags "$0" "$@";; esac
set -eu

# dispatch.sh: filesystem-router for util/ subcommands.
# `util <name> [args...]` execs util/<name>[.sh]. Adding a command is just
# dropping a new util/<name>.sh file (symlinked-in private scripts work too).
#
# CC0: This work has been marked as dedicated to the public domain.
# https://creativecommons.org/publicdomain/zero/1.0/

here=$(dirname "$(realpath "$0")")

# `here` is resolved dynamically so the router also works through a symlink.
# shellcheck source=util/lib.sh
. "$here/lib.sh"

###

# optional private overlay: scripts-private symlinked in as ../private
priv="$here/../private/util"

_util_list() {
	_util_commands "$here"
}

script="${1:-}"

if [ -z "$script" ]; then
	echo "usage: util <command> [args...]"
	echo ""
	echo "commands:"
	_util_list | sed 's/^/  /'
	exit 1
fi

if [ -f "$here/$script" ]; then
	shift
	exec "$here/$script" "$@"
elif [ -f "$here/${script}.sh" ]; then
	shift
	exec "$here/${script}.sh" "$@"
elif [ -d "$priv" ] && [ -f "$priv/$script" ]; then
	shift
	exec "$priv/$script" "$@"
elif [ -d "$priv" ] && [ -f "$priv/${script}.sh" ]; then
	shift
	exec "$priv/${script}.sh" "$@"
else
	echo "Unknown util <$script>" >&2
	echo "run 'util' with no arguments to list commands" >&2
	exit 1
fi
